import React, { useEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import ProductCard from './ProductCard';
import { useProducts } from './hooks';
import './GroceryStore.css';

const ProductListPage = () => {
  const { products, loading, error, fetchAllProducts } = useProducts();
  const [filteredProducts, setFilteredProducts] = useState([]);
  const [category, setCategory] = useState(null);
  const location = useLocation();

  useEffect(() => {
    fetchAllProducts();
  }, []);

  useEffect(() => {
    const categoryName = new URLSearchParams(location.search).get('category');
    setCategory(categoryName);
    if (categoryName) {
      setFilteredProducts(
        products.filter((p) => p.category.toLowerCase() === categoryName.toLowerCase())
      );
    } else {
      setFilteredProducts(products);
    }
  }, [location.search, products]);

  if (loading) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '50vh' }}>
        <div>Loading products...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '50vh' }}>
        <div>Error: {error}</div>
      </div>
    );
  }

  return (
    <div className="container" style={{ paddingTop: '2rem' }}>
      <h2 className="main-title">
        {category ? <span className="text-green">{category}</span> : 'All'} <span className="text-green">Products</span>
      </h2>
      <div className="products-grid">
        {filteredProducts.map((product) => (
          <ProductCard 
            key={product.id} 
            product={product} 
            onAddToCart={() => {}} // Not implemented for this page
          />
        ))}
      </div>
    </div>
  );
};

export default ProductListPage;
